export const getAgeFromDob = (dob, format = 'DD/MM/YYYY') => {
  const date = moment(dob, format, true)
  if (date._isValid) {
    const years = moment().diff(date, 'years', true)
    const months = moment().diff(date, 'months', true)
    const days = moment().diff(date, 'days', true)
    return {
      years,
      months,
      days,
    }
  } else {
    return undefined
  }
}

