export const getAddress = (addrData, provinces, cities) => {
  if (isEmpty(addrData) || isEmpty(provinces) || isEmpty(cities)) {
    return {}
  } else {
    const addr = {}
    addr.province_code = get(addrData, 'province_code', '')
    addr.city_code = get(addrData, 'city_code', '')
    addr.postal_code = get(addrData, 'postal_code', '')
    addr.address = get(addrData, 'address', '')
    addr.province_name = find(provinces, {
      province_code: addr.province_code,
    }).province_name
    const citydata = find(cities, { city_code: addr.city_code })
    addr.city_name = citydata.city_name
    addr.region = citydata.region
    return addr
  }
}

export function getGlobalStateObject(agentDetails = {}) {
  let isAggregatorAgent = false
  let isInternalAgent = false
  let isGojekAgent = false
  let isStaffAgent = false
  let isAggregatorStaffAgent = false
  let isRetailStaffAgent = false
  let isAggregatorDownlineAgent = false
  const tags = lodashGet(agentDetails, 'agent_tags', []) || []
  const isRMMapped = !isEmpty(agentDetails?.tag_handler_details)
  tags.forEach((tag) => {
    switch (tag.code) {
      case 'GOJEK':
        isGojekAgent = true
        break
      case 'AGGREGATOR-STAFF':
        isAggregatorStaffAgent = true
        break
      case 'RETAIL-STAFF':
        isRetailStaffAgent = true
        break
      default:
        break
    }
    switch (tag.tag_type) {
      case 'aggregator':
        isAggregatorAgent = true
        break
      case 'aggregator-downline':
        isAggregatorDownlineAgent = true
        break
      case 'internal':
        isInternalAgent = true
        break
      case 'staff':
        isStaffAgent = true
        break
      default:
        break
    }
  })
  return {
    agentDetails,
    isAggregatorAgent,
    isInternalAgent,
    isGojekAgent,
    isStaffAgent,
    isAggregatorStaffAgent,
    isRetailStaffAgent,
    isRMMapped,
    getAgentDetailData: agentDetails,
    isGojekDriver: isGojekAgent,
    isGuardianAgentLogin: cookies.get(LOGIN_AS_GURDIAN) || false,
    isAggregatorDownlineAgent,
  }
}

export function formatMoney(
  amount,
  decimalCount = 2,
  currSymbol = 'Rp',
  decimal = ',',
  thousands = '.'
) {
  try {
    decimalCount = Math.abs(decimalCount)
    decimalCount = isNaN(decimalCount) ? 2 : decimalCount

    const negativeSign = amount < 0 ? '- ' : ''

    const i = parseInt((amount = Math.abs(Number(amount) || 0).toFixed(decimalCount))).toString()
    const j = i.length > 3 ? i.length % 3 : 0

    return (
      negativeSign +
      currSymbol +
      (j ? i.substr(0, j) + thousands : '') +
      i.substr(j).replace(/(\d{3})(?=\d)/g, '$1' + thousands) +
      (decimalCount
        ? decimal +
          Math.abs(amount - i)
            .toFixed(decimalCount)
            .slice(2)
        : '')
    )
  } catch (e) {
    // no message has been returned so left empty in this case
  }
}
export function formatNumber(amount, { prefix, suffix }) {
  if (_.isNil(amount)) return ''
  let _amount = String(amount).replace('.', ',')
  if (prefix) _amount = `${prefix} ${_amount}`
  if (suffix) _amount = `${_amount} ${suffix}`
  return _amount
}

export function formatPercentage(amount) {
  if (_.isNil(amount)) return ''
  let _amount = String(amount).replace('.', ',')
  return `${_amount}%`
}

export function getConvertedCurrency(amount, exchangeRate = 1, decimalCount = 0) {
  decimalCount = Math.abs(decimalCount)
  decimalCount = isNaN(decimalCount) ? 2 : decimalCount

  const i = parseInt((amount = Math.abs(Number(amount) || 0).toFixed(decimalCount))).toString()

  return (i / exchangeRate).toFixed(decimalCount)
}
export function getIDRCurrency(amount, exchangeRate, decimalCount = 2) {
  decimalCount = Math.abs(decimalCount)
  decimalCount = isNaN(decimalCount) ? 2 : decimalCount

  const i = parseInt((amount = Math.abs(Number(amount) || 0).toFixed(decimalCount))).toString()

  return i * exchangeRate
}

