export function queryBuilder(finalFilter) {
  const queryArray = []
  Object.keys(finalFilter).forEach((key) => {
    const keyValue = finalFilter[key]
    let query = ''
    const identifier = queryArray.length ? '&' : '?'
    if (Array.isArray(keyValue)) {
      keyValue.forEach((value) => {
        query += `${query ? '&' : ''}${key}=${value}`
      })
    } else if (keyValue) {
      query += `${key}=${keyValue}`
    }
    if (query) {
      queryArray.push(`${identifier}${query}`)
    }
  })
  return queryArray.join('')
}

export function urlMapper(url, params = {}) {
  let urlString = url
  Object.keys(params).forEach((key) => {
    urlString = urlString.replace(`{${key}}`, params[key])
    return urlString
  })
  return urlString
}

export function getQueryParams(params, url) {
  const href = url || window.location.href
  // this expression is to get the query strings
  const reg = new RegExp('[?&]' + params + '=([^&#]*)', 'i')
  const queryString = reg.exec(href)
  return queryString ? queryString[1] : null
}

export function getDiffaultForAutoSuggest(data, dataKey, displayKey, defaultData) {
  if (!dataKey || !displayKey || dataKey === displayKey || !data) {
    // if dataKey and display key same then return same data
    return defaultData
  }
  const item = find(data, {
    [dataKey]: defaultData,
  })

  return item && item[displayKey]
}

