export const validatePaymentTimeCounter = (date) => {
  const startDateTime = new Date(date)
  const startStamp = startDateTime.getTime()

  let newDate = new Date()
  let newStamp = newDate.getTime()

  newDate = new Date()
  newStamp = newDate.getTime()
  let diff = Math.round((newStamp - startStamp) / 1000)

  const noofDay = Math.floor(diff / (24 * 60 * 60))
  diff = diff - noofDay * 24 * 60 * 60
  const hour = Math.floor(diff / (60 * 60))
  if (!date || noofDay >= 3) {
    return false
  } else if (noofDay < 3 && hour < 24) {
    return true
  }
}

