export function copySharingData(sharingDate, successMsg = 'Menyalin ke clipboard berhasil') {
  // this handle copy referral code
  if (window.PPBridge) {
    // this for android device
    window.PPBridge.copy(sharingDate)
    return true
  } else {
    if (navigator.clipboard) {
      navigator.clipboard.writeText(sharingDate).then(
        function () {
          NotificationManager.success(successMsg)
          return true
        },
        function (e) {
          if (copyToClipboard(sharingDate)) {
            NotificationManager.success(successMsg)
            return true
          } else {
            NotificationManager.success('Gagal Menyalin')
            return false
          }
        }
      )
    } else {
      // this is helpful to copy to data
      if (copyToClipboard(sharingDate)) {
        NotificationManager.success(successMsg)
      }
    }
  }
}

