// convert the number into K, M and B
export const convertNumberToMillions = (x) => {
  if (isNaN(x)) return x

  if (x < 9999) {
    return x
  }
  if (x < 1000000) {
    return Math.round(x / 1000) + ' K'
  }
  if (x < 10000000) {
    return x / 1000000 + ' Juta'
  }
  if (x < 1000000000) {
    return Math.round(x / 1000000) + ' juta'
  }
  if (x < 1000000000000) {
    return Math.round(x / 1000000000) + ' B'
  }

  return '1T+'
}

export const getTotalPolicyPremium = (addValues = [], subtractValues = []) => {
  const totalSum = addValues.reduce((acc, curr) => acc + curr, 0)
  const totalSubtract = subtractValues.reduce((acc, curr) => acc + curr, 0)

  return totalSum - totalSubtract
}

export const getNameErrorMsg = (value = '') => {
  let errorText = ''
  const isNumber = value.match(/[\d+]/g)
  if (value && value.length < 3) {
    if (value.match(/^[A-Za-z]{2,}/)) {
      errorText = ERROR_LANG.nameErrorRequied
    } else {
      errorText = ERROR_LANG.nameValidationError
    }
  } else if (value && !value.match(/^[A-Za-z]{1,}/)) {
    errorText = ERROR_LANG.nameMustBeginWithLetter
  } else if (value && isNumber && isNumber.length > 5) {
    errorText = ERROR_LANG.nameMayContain5digit
  } else {
    errorText = ERROR_LANG.nameValidationError
  }

  return errorText
}

export const getSlabLevelPercentage = (slabs, gwp, currentSlab, slabData) => {
  // blocks premium are not equally distributed that's why we are need to calculate
  // on basis of 33% block container
  let percentage = 0
  switch (currentSlab) {
    case 'SILVER': {
      const bronzeSlabData = find(slabs, { badge: 'BRONZE' })
      percentage =
        (gwp - bronzeSlabData.premium_limit) /
        (slabData.premium_limit - bronzeSlabData.premium_limit)
      // 37 percentage is the first block with margin
      // 32 is the percentage block for current block that is for silver to gold
      percentage = 37 + percentage * 32
      return percentage
    }
    case 'GOLD': {
      const GoldSlabData = find(slabs, { badge: 'SILVER' })
      percentage =
        (gwp - GoldSlabData.premium_limit) / (slabData.premium_limit - GoldSlabData.premium_limit)
      // 37 percentage is the first block with margin
      percentage = 68 + percentage * 33
      return percentage
    }
    case 'PLATINUM': {
      // if slab is platinum means already achieve 100%
      percentage = 100
      return percentage
    }
    default: {
      // handle the bronze level
      percentage = (gwp / slabData.premium_limit) * 37
      return percentage
    }
  }
}

export const getBadgePercentage = (badgeData = {}) => {
  // handle the percentage for the number line
  const {
    slabs,
    actual_slab: actualSlab,
    actual_gwp: actualGwp,
    estimated_gwp: estimatedGwp,
    estimated_slab: estimatedSlab,
  } = badgeData
  const actualSlabData = find(slabs, { badge: actualSlab }) || {}
  const estimatedSlabData = find(slabs, { badge: estimatedSlab }) || {}
  const actualPercentage = getSlabLevelPercentage(slabs, actualGwp, actualSlab, actualSlabData)
  const estimatedPercentage = getSlabLevelPercentage(
    slabs,
    estimatedGwp,
    estimatedSlab,
    estimatedSlabData
  )

  return {
    estimatedPercentage,
    actualPercentage,
  }
}

export const generateMonthYearMap = () => {
  // handle the month year
  // initialMonth is an integer
  const initialMonth = 8 // month index start from it denotes sept 2020
  const initialYear = 2020 // initial year at the time of release
  let currentMonth = moment().month()
  let currentYear = moment().year()
  const data = []

  function getData(month, year) {
    return {
      display: `${moment().month(month).format('MMM')} - ${year}`,
      value: `${month + 1}-${year}`,
    }
  }

  while (currentYear >= initialYear) {
    if (currentYear > initialYear) {
      while (currentMonth > 0) {
        data.push(getData(currentMonth, currentYear))
        currentMonth--
      }
      if (currentMonth === 0) {
        data.push(getData(currentMonth, currentYear))
        currentMonth = 11
        currentYear--
      }
    } else {
      while (currentMonth >= initialMonth) {
        data.push(getData(currentMonth, currentYear))
        currentMonth--
      }
      currentYear = undefined
    }
  }
  // {
  //   display: 'Sept 2020',
  //   value: '9-2020'
  // }
  return data
}

