export const getTaxForAgentAmount = (amount, taxSlabs = []) => {
  let tax = 0
  let taxableAmount = amount
  for (let index = 0; index < taxSlabs.length; index++) {
    // calculate the tax
    if (taxableAmount <= 0) break
    const slab = taxSlabs[index]
    if (slab.max && slab.max <= amount) {
      tax += (slab.max - slab.min) * slab.percentage
      taxableAmount = taxableAmount - slab.max
    } else {
      tax += taxableAmount * slab.percentage
      taxableAmount = 0
    }
  }
  return tax
}

