export const getGreetingMsg = () => {
  // 05:00 - 10:00 -> "Selamat pagi"
  // 10:01 - 16:00 -> "Selamat siang"
  // 16:01 - 18:00 -> "Selamat sore"
  // 18:01 - 04:59 -> " Selamat Malam"
  const time = parseFloat(moment().format('H.MM'))
  if (time >= '5.00' && time <= '10.00') {
    return 'goodMorning'
  } else if (time >= '10.01' && time <= '16.00') {
    return 'goodAfterNoon'
  } else if (time >= '16.01' && time <= '18.00') {
    return 'goodAfterNoon2'
  } else if ((time >= '18.01' && time <= '23.59') || time <= '4.59') {
    return 'goodNight'
  }
}

