export const formatNPWP = (value) => {
  if (typeof value === 'string') {
    return value.replace(/(\d{2})(\d{3})(\d{3})(\d{1})(\d{3})(\d{3})/, '$1.$2.$3.$4-$5.$6')
  }
}

export const addCountryCode = (mobileNo) => {
  let phoneNumber = mobileNo
  if (!phoneNumber.includes('84-')) {
    const firstDigit = phoneNumber.substr(0, 1)
    if (firstDigit === '0') {
      phoneNumber = phoneNumber.replace('0', '')
    }
    const startNumber = phoneNumber.substr(0, 2)
    const restNumber = phoneNumber.substr(2, phoneNumber.length)
    if (startNumber !== '84' && restNumber.length <= 9) {
      phoneNumber = `84-${phoneNumber}`
    } else if (phoneNumber.length === 9) {
      // phone Number length in vietnam
      phoneNumber = `84-${phoneNumber}`
    }
  }
  return phoneNumber
}

export const extractValues = (obj) => {
  let result = ''
  const encounteredValues = new Set()

  const traverse = (obj) => {
    if (Array.isArray(obj)) {
      obj.forEach((item) => traverse(item))
    } else if (typeof obj === 'object' && obj !== null) {
      Object.values(obj).forEach((value) => traverse(value))
    } else {
      if (!encounteredValues.has(obj)) {
        result += obj + '\n'
        encounteredValues.add(obj)
      }
    }
  }

  traverse(obj)

  return result
}

export const mapNumberToMonth = (number, short = false) => {
  const shortMonths = [
    'Jan',
    'Feb',
    'Mar',
    'Apr',
    'Mei',
    'Jun',
    'Jul',
    'Ags',
    'Sep',
    'Okt',
    'Nov',
    'Des',
  ]

  const months = [
    'Januari',
    'Februari',
    'Maret',
    'April',
    'Mei',
    'Juni',
    'Juli',
    'Agustus',
    'September',
    'Oktober',
    'November',
    'Desember',
  ]

  if (number >= 0 && number <= 11) {
    if (short) {
      return shortMonths[number]
    } else {
      return months[number]
    }
  }
}

export const generateYearArray = (endYear) => {
  const currentYear = 2021
  const yearArray = []

  if (endYear >= currentYear) {
    for (let year = currentYear; year <= endYear; year++) {
      yearArray.push({ year })
    }
  }

  return yearArray
}
