export const shareTextNative = (subject, message, callback = () => {}) => {
  // call this function to share the msg only to native share
  try {
    if (window.PPBridge.share) {
      window.PPBridge.share(subject, message)
    } else {
      callback()
    }
  } catch (e) {
    callback(e)
  }
}

