export const getFCMToken = () => {
  return new Promise((resolve) => {
    try {
      if (window.PPBridge.getFCMToken) {
        /**
         * Callback to receive the token
         * @param {object} bridgeMsg
         * @param {string} bridgeMsg.keyName
         * @param {string} bridgeMsg.status
         * @param {string} bridgeMsg.data stringifed JSON
         */
        window.response = (bridgeMsg) => {
          const msg = JSON.parse(JSON.stringify(bridgeMsg));
          console.log('Bridge Response:', msg);
        
          if (msg.keyName === 'getFCMToken' && msg.status === '200') {
            const payload = JSON.parse(msg.data)
            console.log('FCM Payload:', payload)
            resolve(payload)
          }
        }
        return window.PPBridge.getFCMToken()
      }
    } catch (error) {
      // if this not exist then show error
        console.error(error)
      return null
    }
  })
}

export const saveFCMToken = (token = '') => {
  return new Promise((resolve) => {
    if (window.PPBridge.saveFCMToken) {
      // this enable the pull refresh
      window.PPBridge.saveFCMToken(token)
      resolve()
    }
  })
}

